gold.schema_ddl:
CREATE TABLE clienti (
    id INT PRIMARY KEY,
    nome TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE
);

CREATE TABLE ordini (
    id INT PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    data_ordine DATE NOT NULL,
    importo_totale NUMERIC(10,2) CHECK (importo_totale >= 0)
);

CREATE TABLE movimenti (
    id INT PRIMARY KEY,
    ordine_id INT NOT NULL REFERENCES ordini(id),
    quantita INT NOT NULL CHECK (quantita > 0),
    tipo_movimento TEXT NOT NULL,
    data_movimento TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
